"""Tk presentation only. No wallet, persistence, signing or monetary logic."""
import tkinter as tk
from tkinter import ttk

def scrolling(parent):
    canvas=tk.Canvas(parent,background='#f3f5f8',highlightthickness=0)
    scrollbar=ttk.Scrollbar(parent,orient='vertical',command=canvas.yview);scrollbar.pack(side='right',fill='y')
    canvas.configure(yscrollcommand=scrollbar.set);canvas.pack(fill='both',expand=True)
    content=ttk.Frame(canvas);window=canvas.create_window(0,0,window=content,anchor='nw')
    content.bind('<Configure>',lambda _:canvas.configure(scrollregion=canvas.bbox('all')))
    canvas.bind('<Configure>',lambda event:canvas.itemconfigure(window,width=event.width))
    canvas.bind('<MouseWheel>',lambda event:canvas.yview_scroll(-int(event.delta/120),'units'))
    return content,canvas

def build(app):
    root=app.root;root.title('Privacy Coin — Wallet UX V1.1 — DEVNET ONLY');root.geometry('1080x860');root.minsize(900,700)
    style=ttk.Style(root);style.theme_use('clam')
    style.configure('TFrame',background='#f3f5f8');style.configure('TLabel',background='#f3f5f8',foreground='#18283b',font=('Segoe UI',10))
    style.configure('TButton',padding=(12,8));style.configure('TLabelframe',background='#f3f5f8');style.configure('TLabelframe.Label',background='#f3f5f8',foreground='#18283b',font=('Segoe UI',11,'bold'))
    style.configure('TCheckbutton',background='#f3f5f8',foreground='#18283b');style.configure('Treeview',rowheight=28,font=('Segoe UI',10))
    root.configure(background='#f3f5f8');frame=ttk.Frame(root,padding=20);frame.pack(fill='both',expand=True)
    ttk.Label(frame,text='Privacy Coin',font=('Segoe UI',22,'bold')).pack(anchor='w')
    ttk.Label(frame,text='DEVNET ONLY  •  Disposable test funds  •  Not safe for real assets',foreground='#994100',font=('Segoe UI',11,'bold')).pack(anchor='w',pady=(0,12))
    defaults=dict(name='',password='',port='48081',destination='',amount='0.000001',fee='0.000000188',max_fee='0.0000005',unit='PC',backup='Wallet-recovery',restore_source='',restore_name='',restore_password='')
    app.vars={key:tk.StringVar(master=root,value=value) for key,value in defaults.items()};app.restore_ack=tk.BooleanVar(master=root,value=False)
    box=ttk.LabelFrame(frame,text='Your wallet',padding=10);box.pack(fill='x')
    ttk.Label(box,text='Wallet name').grid(row=0,column=0,sticky='w');app.wallet_picker=ttk.Combobox(box,textvariable=app.vars['name'],width=24);app.wallet_picker.grid(row=1,column=0,sticky='we',padx=(0,12))
    app.entry(box,'Password (12–1024 characters)','password',0,1,26,True)
    # Entry occupies columns 1–2; actions have their own columns.
    for column,(label,fn) in enumerate((('Create',app.create),('Open',app.open),('Lock / close',app.close_wallet)),3):ttk.Button(box,text=label,command=fn).grid(row=1,column=column,padx=4)
    ttk.Button(box,text='Refresh list',command=lambda:app.run('hello',{},app.hello)).grid(row=1,column=6,padx=4)
    ttk.Label(box,text='Choose an existing name to open, or enter a new name to create. Passwords are cleared after use.').grid(row=2,column=0,columnspan=7,sticky='w',pady=(8,0))
    app.active_wallet=tk.StringVar(root,value='No wallet open');ttk.Label(frame,textvariable=app.active_wallet,font=('Segoe UI',12,'bold')).pack(anchor='w',pady=(12,3))
    app.status=tk.StringVar(root,value='Starting private WSL wallet backend…');ttk.Label(frame,textvariable=app.status,wraplength=1000).pack(anchor='w',pady=(0,8))
    app.tabs=ttk.Notebook(frame);app.tabs.pack(fill='both',expand=True)
    pages={name:ttk.Frame(app.tabs,padding=16) for name in ('Overview','Receive','Send','History','Backup / restore','Network / details')}
    for name,page in pages.items():app.tabs.add(page,text=name)
    app.pages=pages;app.summary={}
    overview,app.overview_canvas=scrolling(pages['Overview']);overview.columnconfigure(0,weight=1);overview.columnconfigure(1,weight=1)
    for index,(key,label) in enumerate((('spendable','Available to send'),('balance','Locally observed chain balance'),('pending_incoming','Pending incoming'),('pending_change','Pending change'),('locked_coinbase','Immature mining rewards'),('locked_normal','Other locked funds'),('reserved_inputs','Reserved by pending spends'),('sufficiently_confirmed_unspent','Policy-confirmed unspent'))):
        card=ttk.LabelFrame(overview,text=label,padding=10);card.grid(row=index//2,column=index%2,sticky='nsew',padx=5,pady=5)
        app.summary[key]=tk.StringVar(root,value='UNKNOWN / unavailable');ttk.Label(card,textvariable=app.summary[key],font=('Segoe UI',16 if index==0 else 13,'bold')).pack(anchor='w')
    app.qualification=tk.StringVar(root,value='Open a wallet, then refresh against a consistent local node.')
    ttk.Label(overview,textvariable=app.qualification,wraplength=780).grid(row=4,column=0,columnspan=2,sticky='w',pady=12)
    ttk.Label(overview,text='All balances are relative to your local validating node. Global freshness: UNKNOWN.\nIndependent network verification is unavailable; chain inclusion is not irreversible finality.',wraplength=780).grid(row=5,column=0,columnspan=2,sticky='w')
    ttk.Button(overview,text='Full scan / refresh',command=app.refresh).grid(row=6,column=0,sticky='w',pady=12)
    receive=pages['Receive'];app.address=tk.StringVar(root,value='Unlock a wallet to display its address.')
    ttk.Label(receive,text='Receive a private payment',font=('Segoe UI',16,'bold')).pack(anchor='w')
    ttk.Label(receive,text='Share only this public PCdv1 address. No seed or viewing key is needed.').pack(anchor='w',pady=12)
    ttk.Entry(receive,textvariable=app.address,state='readonly',font=('Consolas',10)).pack(fill='x',pady=10)
    ttk.Button(receive,text='Copy address',command=app.copy_address).pack(anchor='w')
    ttk.Label(receive,text='The address is long: Copy address copies the complete value.\nRefresh after receiving or mining. Mining rewards mature after 60 blocks.\nA pending or locked payment cannot be spent yet.',wraplength=900).pack(anchor='w',pady=20)
    send,app.send_canvas=scrolling(pages['Send']);send.columnconfigure(0,weight=1);send.columnconfigure(1,weight=1)
    ttk.Label(send,text='Send a private Devnet payment',font=('Segoe UI',16,'bold')).grid(row=0,column=0,columnspan=4,sticky='w')
    ttk.Label(send,text='Amount and both fees use the selected unit. 1 PC = 1,000,000,000,000 atomic units.').grid(row=1,column=0,columnspan=4,sticky='w',pady=8)
    units=ttk.Combobox(send,textvariable=app.vars['unit'],values=('PC','atomic'),state='readonly',width=12);units.grid(row=2,column=0,sticky='w');units.bind('<<ComboboxSelected>>',app.change_unit)
    for index,(label,key) in enumerate((('Recipient PCdv1 address','destination'),('Payment amount','amount'),('Transaction fee','fee'),('Maximum permitted fee','max_fee'))):app.entry(send,label,key,3+index*2,0,94 if index==0 else 30)
    app.send_button=ttk.Button(send,text='Review private payment…',command=app.review);app.send_button.grid(row=11,column=0,sticky='w',pady=12)
    ttk.Label(send,text='Review does not broadcast. Final authorization requires typing CONFIRM.\nThe review shows amount, fee and total separately. An UNKNOWN submission blocks\nfurther sends: preserve the original state and reconcile; never blindly resend.',wraplength=900).grid(row=12,column=0,columnspan=4,sticky='w')
    history=pages['History'];ttk.Label(history,text='Owned outputs and local outgoing attempts',font=('Segoe UI',14,'bold')).pack(anchor='w')
    pager=ttk.Frame(history);pager.pack(fill='x',pady=4)
    app.history_newer=ttk.Button(pager,text='Newer outputs',command=lambda:app.page_history(-1),state='disabled');app.history_newer.pack(side='left')
    app.history_older=ttk.Button(pager,text='Older outputs',command=lambda:app.page_history(1),state='disabled');app.history_older.pack(side='left',padx=8)
    app.history_position=tk.StringVar(app.root,value='Refresh to view owned outputs');ttk.Label(pager,textvariable=app.history_position).pack(side='left')
    ttk.Label(history,text='Outputs include change; this is not a net payment ledger. Outgoing history from other tools may be incomplete.\nCHAIN_INCLUDED means local inclusion, not finality. Full transaction identifiers are in Network / details.',wraplength=950).pack(anchor='w',pady=8)
    app.history_table=ttk.Treeview(history,columns=('kind','state','amount','fee'),show='headings',height=12)
    for key,label,width in (('kind','Entry',160),('state','Status relative to node',260),('amount','Amount (PC)',190),('fee','Fee (PC)',160)):
        app.history_table.heading(key,text=label);app.history_table.column(key,width=width,anchor='w')
    app.history_table.pack(fill='both',expand=True)
    backup,app.backup_canvas=scrolling(pages['Backup / restore'])
    ttk.Label(backup,text='Keep the encrypted backup AND its password, stored separately. Either missing can make recovery impossible.\nAnyone with both can spend. Do not delete the original wallet until recovery is verified.',wraplength=780).pack(anchor='w',pady=(0,12))
    create=ttk.LabelFrame(backup,text='1. Create an encrypted backup of the open wallet',padding=12);create.pack(fill='x',pady=6)
    app.entry(create,'New backup name (no overwrite)','backup',0,0,38);ttk.Button(create,text='Create encrypted backup',command=app.backup).grid(row=1,column=2,padx=12)
    restore=ttk.LabelFrame(backup,text='2. Restore an existing encrypted backup to a NEW wallet name',padding=12);restore.pack(fill='x',pady=6)
    ttk.Label(restore,text='Restore source (backup name)').grid(row=0,column=0,sticky='w');app.backup_picker=ttk.Combobox(restore,textvariable=app.vars['restore_source'],width=38);app.backup_picker.grid(row=1,column=0,columnspan=2,sticky='we',pady=(3,8))
    app.entry(restore,'New destination wallet name','restore_name',2,0,38)
    app.entry(restore,'Backup encryption password','restore_password',4,0,38,True)
    ttk.Checkbutton(restore,text='I understand that this alias controls the SAME funds.',variable=app.restore_ack).grid(row=6,column=0,columnspan=4,sticky='w',pady=8)
    ttk.Label(restore,text='Do not spend independently from the original and restored wallets.',wraplength=730).grid(row=7,column=0,columnspan=4,sticky='w')
    ttk.Button(restore,text='Restore encrypted backup',command=app.restore).grid(row=8,column=0,sticky='w',pady=(8,0))
    ttk.Label(backup,text='A stale backup cannot contain later payment attempts. Preserve the newest original state.\nRestore never overwrites a wallet. It opens the new alias and runs a full scan.\nUnknown submission reservations may require manual investigation; restoring is not a way to clear them.',wraplength=780).pack(anchor='w',pady=12)
    detail=pages['Network / details'];line=ttk.Frame(detail);line.pack(fill='x')
    ttk.Label(line,text='Loopback RPC port').pack(side='left');ttk.Entry(line,textvariable=app.vars['port'],width=8).pack(side='left',padx=8);ttk.Button(line,text='Connect',command=app.connect).pack(side='left')
    app.network_status=tk.StringVar(root,value='No current node observation.');ttk.Label(detail,textvariable=app.network_status,wraplength=950).pack(anchor='w',pady=8)
    details=ttk.Notebook(detail);details.pack(fill='both',expand=True)
    balances=ttk.Frame(details);transactions=ttk.Frame(details);details.add(balances,text='Exact atomic balances / chain');details.add(transactions,text='Transaction identifiers / raw amounts')
    app.overview=app.text(balances);app.overview.pack(fill='both',expand=True);app.history=app.text(transactions);app.history.pack(fill='both',expand=True)
    ttk.Label(frame,text='Full sync • Phase 5 / 6A security blockers open • Local wallet pilot, no independent audit',foreground='#994100').pack(anchor='w',pady=(10,0))
